    nxt[1] = 1;
    for (int v = 2; v <= cn; v++) {
        long long p = par[v - 1];
        tin[v] = nxt[p];
        nxt[p] += sz[v];
        nxt[v] = tin[v] + 1;
    }
    long long size = 1;
    while (size < cn) size *= 2;
    const long long LOW = -(1LL << 62);
