import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] par = new long[(int) n];
        for (int i = 0; i < par.length; i++) par[i] = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] ops = new long[(int) q][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        long[] sz = new long[cn + 1];
        long[] tin = new long[cn + 1];
        long[] nxt = new long[cn + 1];
        java.util.Arrays.fill(sz, 1);
        for (int v = cn; v >= 2; v--) sz[(int) par[v - 1]] += sz[v];
        nxt[1] = 1;
        for (int v = 2; v <= cn; v++) {
            int p = (int) par[v - 1];
            tin[v] = nxt[p];
            nxt[p] += sz[v];
            nxt[v] = tin[v] + 1;
        }
        int size = 1;
        while (size < cn) size *= 2;
        long low = -(1L << 62);
        long[] tree = new long[2 * size];
        java.util.Arrays.fill(tree, low);
        for (int v = 1; v <= cn; v++) tree[size + (int) tin[v]] = a[v - 1];
        for (int v = size - 1; v >= 1; v--) tree[v] = Math.max(tree[2 * v], tree[2 * v + 1]);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            long kind = ops[k][0];
            int v = (int) ops[k][1];
            long x = ops[k][2];
            if (kind == 1) {
                int u = size + (int) tin[v];
                tree[u] = x;
                for (u /= 2; u >= 1; u /= 2) tree[u] = Math.max(tree[2 * u], tree[2 * u + 1]);
            } else {
                int lo = size + (int) tin[v];
                int hi = lo + (int) sz[v];
                long res = low;
                while (lo < hi) {
                    if ((lo & 1) == 1) res = Math.max(res, tree[lo++]);
                    if ((hi & 1) == 1) res = Math.max(res, tree[--hi]);
                    lo /= 2;
                    hi /= 2;
                }
                if (out.length() > 0) out.append(" ");
                out.append(res);
            }
        }
        System.out.println(out);
    }
}
